Lemma alloc_exit : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' xs1 xs3 xs4 xs5 xs6 xs7 xs10 : word)
    (A size spa lo shi ff fp : Z) (LF : list fframe) (m mx : mem) (pad : list cell) (j24 hjunk sh16 junkB j7 : list byte) (bflag : byte),
  rw_cells bsegs mx spa pad -> Z.of_nat (cells_size pad) = bv_unsigned sp + -128 - spa -> lo <= spa ->
  rw_cells bsegs mx (bv_unsigned sp + -128) (alloc_frame s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra j24) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 bflag] ->
