  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi ->
  munch (alloc_W2 lo sp A size ff fp) m mx -> wmono bsegs m mx ->
  (forall m', munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z mx m' -> wmono bsegs mx m' ->
     rw_cells bsegs m' A [CB (Z.to_nat size) (firstn (Z.to_nat size) junkB)] /\ rw_cells bsegs m' (A + size) (CookieCells j7)) ->
  lo + 144 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
